@Composable
fun AIIcon(name: AIIconName, modifier: Modifier = Modifier, color: Color = AITheme.colors.mutedForeground) {
    Canvas(modifier.size(16.dp)) {
        scale(size.width / 24f, size.height / 24f, pivot = androidx.compose.ui.geometry.Offset.Zero) {
            drawPath(iconPath(name), color, style = Stroke(2f, cap = StrokeCap.Round, join = StrokeJoin.Round))
        }
    }
}
